import { platform,isPages } from './platform-client.js';
import qrcode from './qr-code.js';
import { statuses,poStatuses,demoOperators,DEMO_OPERATOR_PASSWORD,salesUnits } from './platform-core.js';
import { genderNames } from './member-store.js';
import { $,esc,money,date,icon,badge,toast,modal,closeModal,empty,formError,downloadCSV } from './ui-kit.js';
import { supplyStatuses,supplySources,supplyIntervals,marginFor } from './supply-core.js';
import { invoiceHtml,downloadInvoiceCsv,invoiceStatusLabels } from './invoice-view.js';
import { memberRef } from './privacy.js';
import { accessScopes } from './access-log.js';
let data,operator=null,view=location.hash.slice(1)||'overview',query='',statusFilter='',salonFilter='',period='30',loading=false,sales=null,salesUnit='month',salesFrom='',salesTo='',marginSalon='',marginProduct='',marginQty=10,currentInvoice=null;
const titles={overview:['ダッシュボード','サロンとディーラーをつなぐ、日々の運用をひとつに。'],sales:['売上集計','期間・店舗ごとの販売金額、受注件数、顧客数を集計し、CSVに出力します。'],orders:['受注管理','お客様の注文と、仕入先への発注状況を確認します。'],purchase:['ディーラー発注','注文から自動作成された発注を受け付け、出荷を進めます。'],products:['商品・在庫','販売価格、仕入単価と、ディーラーの販売可能在庫を管理します。'],salons:['サロン管理','参加サロンの設定と紹介リンクを管理します。'],members:['会員管理','会員とサロン・担当スタッフのつながりを確認します。'],settlements:['精算管理','販売・仕入・運用料金を注文ごとに確認します。'],supply:['加盟店発注','加盟店からの仕入発注を受け付け、出荷を進めます。定期発注もここで確認できます。'],invoices:['請求書','加盟店ごとに月末で締めて、1か月分の請求書を発行します。'],margins:['店販の取り分','ECで売れたときと店頭で売ったときに、サロンに残る金額を比べます。'],activity:['操作履歴','注文と管理操作の記録を確認します。'],access:['アクセス記録','お客様の個人情報を、誰が・いつ・何件受け取ったかを確認します。']};
const navs=[['overview','grid','ダッシュボード'],['sales','wallet','売上集計'],['orders','bag','受注管理'],['purchase','truck','ディーラー発注'],['supply','box','加盟店発注'],['invoices','wallet','請求書'],['products','box','商品・在庫'],['salons','store','サロン管理'],['members','users','会員管理'],['settlements','wallet','精算管理'],['margins','leaf','店販の取り分'],['activity','clock','操作履歴'],['access','shield','アクセス記録']];
const allowed=()=>navs.filter(([id])=>operator?.role==='admin'||operator?.role==='salon'&&!['products','activity'].includes(id)||operator?.role==='dealer'&&['overview','purchase','products','access'].includes(id));
const roleName=()=>({admin:'管理会社',salon:'美容室',dealer:'ディーラー'}[operator?.role]||'');
const brand=()=>'<div class="brand"><span class="brand-mark">S</span><div class="brand-word">SALON STATION<small>PARTNER CONSOLE</small></div></div>';
const scopedOrders=()=>data.orders.filter(o=>period==='all'||new Date(o.createdAt)>=new Date(Date.now()-Number(period)*86400000));
const activeOrders=()=>scopedOrders().filter(o=>!['cancelled','returned'].includes(o.status));
const sum=(rows,key)=>rows.reduce((a,r)=>a+Number(r[key]||0),0);
function filterRows(rows){return rows.filter(o=>(!statusFilter||o.status===statusFilter)&&(!salonFilter||o.salonId===salonFilter)&&JSON.stringify([o.id,o.orderId,o.name,o.sku,o.salonName,o.customer?.name,o.email,o.staffId]).toLowerCase().includes(query.toLowerCase()));}
function login(){operator=null;$('#app').innerHTML=`<main class="login-layout"><section class="login-brand-side">${brand()}<div><div class="eyebrow">CONNECTED COMMERCE FOR SALONS</div><h1>サロンのその先に、<br>新しいつながりを。</h1><p>お客様の注文から、ディーラーの出荷まで。<br>すべてのパートナーが、同じ流れの中で。</p></div><p>SALON STATION / OPERATIONS PLATFORM</p></section><section class="login-form-side"><div class="login-box"><div class="eyebrow">WELCOME BACK</div><h2>運営管理にログイン</h2><p>アカウントの役割に応じた画面を表示します。</p><form id="operator-login"><label>メールアドレス<input name="email" type="email" value="admin@example.test" autocomplete="username" required></label><label>パスワード<input name="password" type="password" value="${DEMO_OPERATOR_PASSWORD}" autocomplete="current-password" required></label><div id="form-error" class="error" role="alert"></div><button class="btn primary full" type="submit">ログイン ${icon('arrow')}</button></form><div class="notice"><b>体験用アカウント</b><br>共通パスワード：${DEMO_OPERATOR_PASSWORD}<br>${isPages?'公開版の権限切り替えはブラウザ内のシミュレーションです。':'ローカル版はサーバーで権限を検証します。架空データ専用です。'}</div><div class="demo-personas">${demoOperators.map(o=>`<button class="btn outline" data-demo-login="${o.id}">${o.role==='admin'?'管理会社':o.role==='salon'?'美容室':o.dealerId==='sena'?'SENA ディーラー':'BOTANICA ディーラー'}で体験</button>`).join('')}</div><div class="form-actions"><a class="text-link" href="./">利用者サイトを見る ${icon('external')}</a><a class="text-link" href="./order.html">加盟店の発注画面 ${icon('external')}</a></div></div></section></main>`;}
function shell(){if(!allowed().some(([id])=>id===view))view='overview';$('#app').innerHTML=`<aside class="sidebar">${brand()}<div class="sidebar-label">WORKSPACE</div><nav class="side-nav" aria-label="管理メニュー">${allowed().map(([id,i,label])=>`<button class="${view===id?'active':''}" data-view="${id}">${icon(i)}<span>${label}</span>${id==='purchase'&&data.purchaseOrders.some(p=>p.status==='pending')?`<b class="nav-count">${data.purchaseOrders.filter(p=>p.status==='pending').length}</b>`:''}${id==='supply'&&operator.role==='admin'&&(data.supplyOrders||[]).some(o=>o.status==='ordered')?`<b class="nav-count">${data.supplyOrders.filter(o=>o.status==='ordered').length}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-help"><b>DEMO WORKSPACE</b>${isPages?'このブラウザに保存されたデモデータを表示しています。':'同じサーバーの利用者サイトと注文が連動します。'}<br>決済・配送はシミュレーションです。</div><div class="operator-card"><span class="avatar">${roleName().slice(0,1)}</span><div><strong>${esc(operator.name)}</strong><small>${roleName()}アカウント</small></div><button class="icon-btn" data-logout aria-label="管理ログアウト">${icon('logout')}</button></div></div></aside><main class="admin-main"><header class="admin-topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-mobile-menu aria-label="管理メニューを開く">${icon('menu')}</button><span>ワークスペース</span>${icon('chevron')}<strong>${titles[view][0]}</strong></div><div class="topbar-tools"><span class="today">${date(new Date())}</span><span class="connection-label"><i class="status-dot"></i>${isPages?'ブラウザ保存':'ローカル接続中'}</span><button class="icon-btn" data-refresh aria-label="最新のデータに更新">${icon('refresh')}</button><a class="btn outline" href="./" target="_blank" rel="noopener">ストアを見る ${icon('external')}</a></div></header><div class="admin-content"><div class="page-title"><div><h1>${titles[view][0]}</h1><p>${titles[view][1]}</p></div>${view==='overview'?`<select id="period" class="period-chip" aria-label="集計期間"><option value="7">直近7日間</option><option value="30">直近30日間</option><option value="all">すべての期間</option></select>`:['orders','purchase','settlements','members','supply','invoices','access'].includes(view)?`<button class="btn outline" data-export>${icon('download')} CSVを出力</button>`:''}</div>${operator.role!=='admin'?`<div class="notice role-info">${roleName()}アカウント：${operator.role==='dealer'?'自社の商品・発注・配送先のみ表示しています。':'自店舗の受注・会員・精算のみ表示しています。'}</div>`:''}<div id="view-content">${viewContent()}</div><div class="admin-foot"><span>SALON STATION Partner Console</span><span>初期サンプル8件を含む架空データ / 最終取得 ${date(new Date(),true)}</span></div></div></main>`;if($('#period'))$('#period').value=period;if($('#filter-status'))$('#filter-status').value=statusFilter;if($('#filter-salon'))$('#filter-salon').value=salonFilter;}
function metrics(){if(operator.role==='dealer')return [{label:'未受付の発注',value:data.purchaseOrders.filter(p=>p.status==='pending').length,suffix:'件',note:'受注確認をお願いします',icon:'bag'},{label:'出荷待ち',value:data.purchaseOrders.filter(p=>p.status==='accepted').length,suffix:'件',note:'追跡番号を登録して出荷',icon:'truck'},{label:'出荷済み',value:data.purchaseOrders.filter(p=>['shipped','delivered'].includes(p.status)).length,suffix:'件',note:'配達完了まで確認できます',icon:'box'},{label:'販売可能な商品',value:data.products.filter(p=>p.stock>0&&p.enabled).length,suffix:'SKU',note:'在庫変更は利用者サイトへ反映',icon:'store'}];return [{label:'商品売上（税込）',value:money(sum(activeOrders(),'subtotal')),note:`対象期間 ${activeOrders().length}件 / 送料を除く`,icon:'wallet'},{label:'受注件数',value:scopedOrders().length,suffix:'件',note:'キャンセル・返品を含む',icon:'bag'},{label:'出荷待ちの発注',value:data.purchaseOrders.filter(p=>['pending','accepted'].includes(p.status)).length,suffix:'件',note:'すべての期間 / 仕入先別',icon:'truck'},{label:operator.role==='salon'?'登録会員数':'稼働サロン数',value:operator.role==='salon'?data.profiles.length:data.salons.filter(s=>s.enabled).length,suffix:operator.role==='salon'?'人':'店舗',note:operator.role==='salon'?'マイサロン登録済み':'サロンごとの受注状況を確認',icon:'store'}];}
function chart(){const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=d.toLocaleDateString('sv-SE');return {label:`${d.getMonth()+1}/${d.getDate()}`,amount:activeOrders().filter(o=>new Date(o.createdAt).toLocaleDateString('sv-SE')===key).reduce((a,o)=>a+o.subtotal,0)};});const max=Math.max(5000,...days.map(d=>d.amount)),x=i=>48+i*71,y=v=>155-v/max*120,points=days.map((d,i)=>`${x(i)},${y(d.amount)}`).join(' ');return `<svg class="sales-chart" viewBox="0 0 500 190" role="img" aria-label="直近7日間の商品売上推移"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#c1d3b8" stop-opacity=".5"/><stop offset="100%" stop-color="#eef4e9" stop-opacity=".1"/></linearGradient></defs>${[0,.5,1].map(n=>`<line x1="43" x2="484" y1="${y(max*n)}" y2="${y(max*n)}" stroke="#edf0e7" stroke-dasharray="3 3"/><text x="0" y="${y(max*n)+4}">${Math.round(max*n).toLocaleString()}</text>`).join('')}<polygon points="48,155 ${points} 474,155" fill="url(#chart-fill)"/><polyline points="${points}" fill="none" stroke="#709269" stroke-width="2.3"/>${days.map((d,i)=>`<circle cx="${x(i)}" cy="${y(d.amount)}" r="3" fill="#fff" stroke="#709269" stroke-width="2"/><text x="${x(i)}" y="180" text-anchor="middle">${d.label}</text>`).join('')}</svg>`;}
function task(iconName,label,description,value,destination,filter,color=''){return `<button class="task-item" data-task="${destination}" data-task-filter="${filter}"><span class="task-icon ${color}">${icon(iconName)}</span><span class="task-copy"><strong>${label}</strong><small>${description}</small></span><b>${value}</b>${icon('chevron')}</button>`;}
function overview(){const m=metrics();return `<div class="metric-grid">${m.map(v=>`<article class="metric"><div class="metric-top"><span>${v.label}</span>${icon(v.icon)}</div><div class="metric-value">${v.value}${v.suffix?`<small>${v.suffix}</small>`:''}</div><div class="metric-bottom">${v.note}</div></article>`).join('')}</div><div class="dashboard-charts"><section class="panel"><div class="panel-head"><div><h2>${operator.role==='dealer'?'発注・出荷の流れ':'売上の推移'}</h2><p>${operator.role==='dealer'?'受付から配達完了まで、順番に操作できます。':'直近7日間の商品売上（税込）'}</p></div><span class="chart-legend"><i></i>${operator.role==='dealer'?'ディーラー直送':'商品売上'}</span></div><div class="chart-box">${operator.role==='dealer'?`<div class="detail-list"><dt>01 受付</dt><dd>発注の内容・数量とお届け先を確認</dd><dt>02 出荷</dt><dd>配送会社・追跡番号を登録</dd><dt>03 お届け</dt><dd>配達完了を記録し、利用者へ反映</dd></div>`:chart()}</div></section><section class="panel"><div class="panel-head"><div><h2>対応が必要な項目</h2><p>優先して確認したいタスク</p></div>${icon('clock')}</div><div class="task-list">${task('bag','未受付の発注','ディーラーの受注確認待ち',data.purchaseOrders.filter(p=>p.status==='pending').length,'purchase','pending')}${operator.role==='admin'?task('box','加盟店発注の受付待ち','本部の受付が必要な仕入発注',(data.supplyOrders||[]).filter(o=>o.status==='ordered').length,'supply','ordered'):''}${task('truck','出荷待ち','受付済み・出荷情報の登録待ち',data.purchaseOrders.filter(p=>p.status==='accepted').length,'purchase','accepted','green')}${operator.role==='dealer'?task('box','在庫切れの商品','在庫数を更新できます',data.products.filter(p=>!p.stock).length,'products','','red'):task('refresh','返品の申請','返品内容の確認・検品待ち',data.orders.filter(o=>o.status==='return_requested').length,'orders','return_requested','red')}</div></section></div><section class="panel"><div class="panel-head"><div><h2>${operator.role==='dealer'?'最新の発注':'最新の受注'}</h2><p>利用者サイトからの注文がここに届きます。</p></div><button class="text-link" data-view="${operator.role==='dealer'?'purchase':'orders'}">すべて見る ${icon('arrow')}</button></div>${operator.role==='dealer'?purchaseTable(data.purchaseOrders.slice(0,5)):orderTable(data.orders.slice(0,5))}</section>${operator.role==='dealer'?'':`<div class="dashboard-bottom"><section class="panel"><div class="panel-head"><h2>サロン別の売上</h2><span class="subtle-note">選択した期間</span></div><div class="salon-ranking">${data.salons.map(s=>({...s,total:sum(activeOrders().filter(o=>o.salonId===s.id),'subtotal'),count:activeOrders().filter(o=>o.salonId===s.id).length})).sort((a,b)=>b.total-a.total).map((s,i)=>`<div class="rank-row"><span class="rank-num">0${i+1}</span><span class="rank-copy"><b>${esc(s.name)}</b><small>${s.count}件のご注文</small></span><strong>${money(s.total)}</strong></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>${operator.role==='admin'?'最近のアクティビティ':'運用のヒント'}</h2></div>${operator.role==='admin'?activityList(data.events.slice(0,4)):'<div class="task-list"><p class="description">サロンの紹介リンクから会員登録すると、店舗とお客様がつながります。購入履歴には注文時点の担当スタッフが記録されます。</p></div>'}</section></div>`}`;}
function filters(statusesMap){return `<div class="filter-bar"><div class="filter-search">${icon('search')}<input id="admin-query" aria-label="一覧を検索" type="search" placeholder="注文番号・名前などで検索" value="${esc(query)}"></div>${statusesMap?`<select id="filter-status" aria-label="状態で絞り込む"><option value="">すべての状態</option>${Object.entries(statusesMap).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select>`:''}${['orders','purchase','settlements','members','supply'].includes(view)?`<select id="filter-salon" aria-label="サロンで絞り込む"><option value="">すべてのサロン</option>${data.salons.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select>`:''}</div>`;}
function orderTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>注文番号 / 日時</th><th>サロン</th><th>お客様</th><th>ご注文金額</th><th>ステータス</th><th></th></tr></thead><tbody>${rows.map(o=>`<tr><td><strong>${o.id}</strong><small>${date(o.createdAt,true)}${o.sample?' / サンプル':''}</small></td><td>${esc(o.salonName)}<small>${esc(o.staffName)}</small></td><td>${esc(o.customer.name)}<small>${o.items.reduce((a,p)=>a+p.quantity,0)}点の商品</small></td><td><strong>${money(o.total)}</strong></td><td>${badge(o.status,statuses[o.status])}</td><td><button class="row-button" data-order="${o.id}">詳細 ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('該当する注文はありません','検索条件を変えるか、利用者サイトからテスト注文してください。');}
function purchaseTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>発注番号</th><th>仕入先 / 販売サロン</th><th>仕入・送料合計</th><th>状態</th><th>操作</th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${p.id}</strong><small>${p.orderId}</small></td><td>${esc(data.dealers.find(d=>d.id===p.dealerId)?.name)}<small>${esc(p.salonName)}</small></td><td>${money(p.total)}</td><td>${badge(p.status,poStatuses[p.status])}</td><td><button class="row-button" data-po="${p.id}">${operator.role==='salon'?'詳細を見る':p.status==='pending'?'発注を確認':p.status==='accepted'?'出荷する':'詳細を見る'} ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('該当する発注はありません','利用者の注文時に、仕入先別の発注が自動作成されます。');}
function productsPage(){const rows=filterRows(data.products);return `<section class="panel"><div class="panel-head"><div><h2>商品一覧 <span class="pill">${data.products.length} SKU</span></h2><p>在庫は引当後の販売可能数です。更新すると利用者サイトへ反映されます。</p></div></div>${filters()}<div class="table-wrap"><table><thead><tr><th>商品</th><th>ディーラー</th><th>売価 / 仕入単価</th><th>販売可能在庫</th><th>公開状態</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="mini-product"><img src="./assets/${p.image}" alt=""><div><strong>${esc(p.name)}</strong><small>${p.sku} / ${p.size}</small></div></div></td><td>${esc(data.dealers.find(d=>d.id===p.dealerId)?.short)}</td><td>${money(p.price)}<small>仕入 ${money(p.cost)} / 卸 ${money(p.wholesalePrice)}</small></td><td class="${p.stock===0?'stock-out':p.stock<10?'stock-low':''}">${p.stock} 点</td><td>${badge(p.enabled?'delivered':'cancelled',p.enabled?'公開中':'非公開')}</td><td><button class="row-button" data-product="${p.id}">編集 ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('商品が見つかりません'):''}</section>`;}
function salonsPage(){const canEdit=s=>operator.role==='admin'||operator.role==='salon'&&operator.salonId===s.id;return `${operator.role==='admin'?`<div class="page-actions"><button class="btn primary" data-salon-new>${icon('store')} 新しい店舗を登録</button></div>`:''}<div class="salon-grid">${data.salons.map(s=>`<article class="salon-card"><div class="between"><div class="salon-avatar">${esc(s.name.slice(0,1))}</div>${badge(s.enabled?'delivered':'cancelled',s.enabled?'受注中':'休止中')}</div><div class="eyebrow">${esc(s.id)}${s.area?' / '+esc(s.area):''}</div><h2>${esc(s.name)}</h2><p>${esc(s.owner)}</p><p class="salon-address">${esc(s.prefecture||'')}${esc(s.city||'')}${esc(s.street||'')}${s.building?' '+esc(s.building):''}${s.prefecture?'':'住所未登録'}<br>TEL ${esc(s.phone||'未登録')}<br>営業時間 ${esc(s.hours||'未登録')} / 定休日 ${esc(s.holiday||'未登録')}</p><div class="salon-kpis"><div><small>登録会員</small><strong>${(data.customerStats||[]).find(x=>x.salonId===s.id)?.members??data.profiles.filter(p=>p.salonId===s.id).length}<small>人</small></strong></div><div><small>累計受注</small><strong>${data.orders.filter(o=>o.salonId===s.id).length}<small>件</small></strong></div><div><small>運用料率</small><strong>${s.feeRate}<small>％</small></strong></div></div><p>担当スタッフ：${s.staff.map(p=>esc(p.name)).join(' / ')||'未登録'}</p><button class="btn outline full" data-salon-link="${s.id}">紹介QR・リンクを確認 ${icon('external')}</button>${canEdit(s)?`<button class="text-link" data-salon-edit="${s.id}">${operator.role==='admin'?'店舗設定を編集':'サロン情報を編集'} ${icon('arrow')}</button>`:''}</article>`).join('')}</div>`;}
// 販売実績集計（仕様書 2.2.5 / AD-006 / RP-001・RP-002）
async function fetchSales(){sales=await platform('/admin/sales','POST',{unit:salesUnit,from:salesFrom||undefined,to:salesTo||undefined});salesFrom=sales.from;salesTo=sales.to;}
async function loadSales(){await fetchSales();if(view==='sales')shell();}
function salesPage(){const r=sales,num=n=>`<td class="num">${money(n)}</td>`;return `<section class="panel"><div class="panel-head"><div><h2>集計条件</h2><p>キャンセル・返品済みを除いた注文を、注文日（日本時間）で集計します。販売金額は商品売上（税込・送料除く）です。</p></div></div><form id="sales-form" class="filter-bar sales-form"><label>集計単位<select name="unit">${Object.entries(salesUnits).map(([k,v])=>`<option value="${k}" ${salesUnit===k?'selected':''}>${v}</option>`).join('')}</select></label><label>開始日<input type="date" name="from" value="${esc(salesFrom)}" required></label><label>終了日<input type="date" name="to" value="${esc(salesTo)}" required></label><button class="btn primary" type="submit">集計する</button></form></section>${!r?'<p class="subtle-note">集計中です…</p>':`<div class="metric-grid">${[['販売金額（税込）',money(r.total.sales)],['受注件数',r.total.orders+' 件'],['顧客数',r.total.customers+' 人'],['集計期間',`${r.from} 〜 ${r.to}`]].map(([l,v])=>`<div class="metric"><div class="metric-top">${l}</div><div class="metric-value sales-metric">${v}</div><div class="metric-bottom">${esc(r.unitName)} / ${r.salons.length}店舗</div></div>`).join('')}</div><section class="panel"><div class="panel-head"><div><h2>店舗別集計 <span class="pill">${r.from} 〜 ${r.to}</span></h2><p>期間合計を店舗ごとに表示します。</p></div><div class="form-actions"><button class="btn outline" data-export-sales="all">${icon('download')} 全店舗集計CSV</button><button class="btn outline" data-export-sales="salon">${icon('download')} 店舗別集計CSV</button></div></div><div class="table-wrap"><table class="sales-table"><thead><tr><th>店舗</th><th class="num">販売金額（税込）</th><th class="num">受注件数</th><th class="num">顧客数</th></tr></thead><tbody>${r.salons.map(s=>`<tr><td>${esc(s.salonName)}<small>${esc(s.salonId)}</small></td>${num(s.sales)}<td class="num">${s.orders}</td><td class="num">${s.customers}</td></tr>`).join('')}<tr class="total"><td>全店舗合計</td>${num(r.total.sales)}<td class="num">${r.total.orders}</td><td class="num">${r.total.customers}</td></tr></tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>${esc(r.unitName)}の推移</h2><p>${r.unit==='range'?'指定期間の合計です。':'期間ごとの店舗別内訳と全店舗合計です。'}</p></div></div>${r.rows.length?`<div class="table-wrap"><table class="sales-table"><thead><tr><th>期間</th><th>店舗</th><th class="num">販売金額（税込）</th><th class="num">受注件数</th><th class="num">顧客数</th></tr></thead><tbody>${r.rows.map(row=>row.salons.filter(s=>s.orders).map(s=>`<tr><td>${esc(row.period)}</td><td>${esc(s.salonName)}</td>${num(s.sales)}<td class="num">${s.orders}</td><td class="num">${s.customers}</td></tr>`).join('')+`<tr class="total"><td>${esc(row.period)}</td><td>全店舗合計</td>${num(row.total.sales)}<td class="num">${row.total.orders}</td><td class="num">${row.total.customers}</td></tr>`).join('')}</tbody></table></div>`:empty('対象期間に注文はありません','期間を変更してお試しください。')}</section>`}`;}
function exportSales(kind){const r=sales;if(!r)return;const stamp=`${r.from}_${r.to}`;if(kind==='all')downloadCSV(`売上集計表_全店舗_${stamp}.csv`,['期間','販売金額（税込）','受注件数','顧客数'],[...r.rows.map(row=>[row.period,row.total.sales,row.total.orders,row.total.customers]),['合計',r.total.sales,r.total.orders,r.total.customers]]);else downloadCSV(`売上集計表_店舗別_${stamp}.csv`,['期間','店舗ID','店舗名','販売金額（税込）','受注件数','顧客数'],[...r.rows.flatMap(row=>row.salons.map(s=>[row.period,s.salonId,s.salonName,s.sales,s.orders,s.customers])),...r.salons.map(s=>['合計',s.salonId,s.salonName,s.sales,s.orders,s.customers])]);toast('CSVのダウンロードを開始しました。');}
const linkStaffOptions=(salonId,selected='')=>'<option value="">指名なし</option>'+(data.salons.find(s=>s.id===salonId)?.staff||[]).map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${esc(s.name)}</option>`).join('');
function memberLink(id){const p=data.profiles.find(p=>p.id===id);if(!p)return;modal('担当店舗の紐付け変更',`<p>${esc(p.name)}<small class="subtle-note">　${esc(p.email)}</small></p><form id="member-link-form" data-member-id="${esc(id)}" class="stack"><label>担当店舗<select name="salonId" id="link-salon">${data.salons.map(s=>`<option value="${s.id}" ${s.id===p.salonId?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>担当スタッフ<select name="staffId" id="link-staff">${linkStaffOptions(p.salonId,p.staffId)}</select></label><p class="subtle-note">変更後の注文から新しい店舗・スタッフが記録されます。過去の注文は変わりません。</p><div id="form-error" class="error" role="alert"></div><div class="form-actions"><button class="btn outline" type="button" data-member="${esc(id)}">戻る</button><button class="btn primary" type="submit">紐付けを保存</button></div></form>`);}
// 本部はお客様の個人情報を見ず、店舗ごとの集計と会員番号だけを扱う（dist/privacy.js）
function customerAggregatesPage(){const stats=data.customerStats||[],t=stats.reduce((a,s)=>({members:a.members+s.members,lineLinked:a.lineLinked+s.lineLinked,newThisMonth:a.newThisMonth+s.newThisMonth,purchasers:a.purchasers+s.purchasers,repeaters:a.repeaters+s.repeaters}),{members:0,lineLinked:0,newThisMonth:0,purchasers:0,repeaters:0}),firstSalon=data.salons.find(s=>s.enabled);
return `<p class="notice role-info">お客様の個人情報（お名前・連絡先・購入履歴）は担当サロンが管理し、本部の画面には表示しません。本部が扱うのは店舗ごとの集計値と、個人を特定しない会員番号だけです。</p><div class="metric-grid">${[['会員数',t.members+'人'],['LINE連携',t.lineLinked+'人'],['今月の新規',t.newThisMonth+'人'],['リピート率',t.purchasers?Math.round(t.repeaters/t.purchasers*1000)/10+'%':'—']].map(([l,v])=>`<div class="metric"><div class="metric-top">${l}</div><div class="metric-value">${v}</div><div class="metric-bottom">全店舗の合計</div></div>`).join('')}</div>
<section class="panel"><div class="panel-head"><div><h2>店舗ごとの会員</h2><p>購入者は、キャンセル・返品を除く注文が1件以上あるお客様です。リピーターは2件以上のお客様です。</p></div></div><div class="table-wrap"><table class="sales-table"><thead><tr><th>店舗</th><th class="num">会員数</th><th class="num">LINE連携</th><th class="num">今月の新規</th><th class="num">購入者</th><th class="num">リピーター</th><th class="num">リピート率</th></tr></thead><tbody>${stats.map(s=>`<tr><td>${esc(s.salonName)}<small>${esc(s.salonId)}</small></td><td class="num">${s.members}</td><td class="num">${s.lineLinked}</td><td class="num">${s.newThisMonth}</td><td class="num">${s.purchasers}</td><td class="num">${s.repeaters}</td><td class="num">${s.repeatRate}%</td></tr>`).join('')}</tbody></table></div></section>
<section class="panel"><div class="panel-head"><div><h2>担当店舗の付け替え</h2><p>加盟店やお客様から伝えられた会員番号で、担当店舗と担当スタッフを変更します。お客様の氏名は本部には表示されません。</p></div></div><form id="member-ref-form" class="filter-bar sales-form"><label>会員番号<input name="ref" placeholder="M-XXXXXXXX" maxlength="12" required></label><label>新しい担当店舗<select name="salonId" id="ref-salon">${data.salons.filter(s=>s.enabled).map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></label><label>担当スタッフ<select name="staffId" id="ref-staff">${firstSalon?linkStaffOptions(firstSalon.id):''}</select></label><button class="btn primary" type="submit">付け替える</button></form><div id="form-error" class="error member-ref-error" role="alert"></div></section>`;}
function membersPage(){if(operator.role==='admin')return customerAggregatesPage();const rows=filterRows(data.profiles.map(p=>({...p,salonName:data.salons.find(s=>s.id===p.salonId)?.name})));return `<p class="notice role-info">お客様の情報は貴店が管理します。本部の画面には、店舗ごとの集計値と会員番号だけが表示されます。担当店舗の付け替えを本部に依頼するときは、会員番号をお伝えください。</p><section class="panel"><div class="panel-head"><h2>サロン会員 <span class="pill">${rows.length} 人</span></h2></div>${filters()}<div class="table-wrap"><table><thead><tr><th>会員番号</th><th>会員名 / メール</th><th>マイサロン</th><th>担当スタッフ</th><th>購入回数</th><th>登録日</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.ref||memberRef(p.id))}</strong></td><td>${esc(p.name)}${p.lineLinked?'<span class="line-pill">LINE</span>':''}<small>${esc(p.email)}</small></td><td>${esc(p.salonName)}</td><td>${esc(data.salons.find(s=>s.id===p.salonId)?.staff.find(s=>s.id===p.staffId)?.name||'指名なし')}</td><td>${data.orders.filter(o=>o.memberId===p.id).length} 回</td><td>${date(p.createdAt)}</td><td><button class="row-button" data-member="${p.id}">詳細 ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('該当する会員はありません'):''}</section>`;}
function settlementsPage(){const rows=filterRows(data.settlements.map(s=>({...s,id:s.orderId})));return `<div class="metric-grid">${[['商品売上',money(sum(rows,'sales'))],['商品仕入',money(sum(rows,'purchase'))],['運用料金',money(sum(rows,'fee'))],['サロン受取見込',money(sum(rows,'proceeds'))]].map(([label,value])=>`<div class="metric"><div class="metric-top">${label}</div><div class="metric-value">${value}</div><div class="metric-bottom">税込・テスト計算</div></div>`).join('')}</div><p class="notice role-info">受取見込＝商品売上 − 商品仕入 − 運用料金。送料は同額を配送費に充当するデモ設定です。実際の決済手数料・振込・税務処理は含みません。返品受付中は未確定、返金完了後に0円へ調整されます。</p><section class="panel"><div class="panel-head"><h2>注文別の精算明細</h2></div>${filters(statuses)}<div class="table-wrap"><table><thead><tr><th>注文 / サロン</th><th>商品売上</th><th>仕入</th><th>運用料金</th><th>受取見込</th><th>状態</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.orderId}<small>${esc(r.salonName)}</small></td><td>${money(r.sales)}</td><td>${money(r.purchase)}</td><td>${money(r.fee)}</td><td><strong>${money(r.proceeds)}</strong>${r.refunded?`<small>返金 ${money(r.refunded)}</small>`:''}</td><td>${badge(r.status,r.pending?'返品処理中・未確定':statuses[r.status])}</td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('対象の明細はありません'):''}</section>`;}
function activityList(rows){return `<div class="activity-list">${rows.map(e=>`<div class="activity-item"><i></i><div><time>${date(e.at,true)}</time><p>${esc(e.action)}</p><small>${esc(e.actor)} / ${esc(e.reference)}</small></div></div>`).join('')}</div>`;}
// ---- アクセス記録（お客様の個人情報を受け取った記録。dist/access-log.js）。値そのものは記録しない。
function accessPage(){const rows=data.accessLogs||[],admin=operator.role==='admin',salonName=id=>id?data.salons.find(s=>s.id===id)?.name||id:'—',scope=admin?'すべての記録です。':operator.role==='salon'?'貴店のお客様の情報についての記録です（ディーラー・DB保守の分を含みます）。':'あなたのアカウントの記録です。';
return `<section class="panel"><div class="panel-head"><div><h2>見られる範囲</h2><p>お客様の個人情報は、役割ごとに必要な範囲だけを渡し、渡したときに記録します。</p></div></div><div class="table-wrap"><table class="scope-table"><thead><tr><th>役割</th><th>見られる情報と記録</th></tr></thead><tbody>${accessScopes.map(([role,text])=>`<tr><td><strong>${esc(role)}</strong></td><td>${esc(text)}</td></tr>`).join('')}</tbody></table></div></section>
<section class="panel access-log"><div class="panel-head"><div><h2>アクセス記録 <span class="pill">最新 ${rows.length} 件</span></h2><p>${scope}同じ画面の再読み込みは30分に1回だけ記録します。氏名や住所などの値は記録しません。</p></div></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>日時</th><th>担当者</th><th>操作</th><th>対象</th><th>お客様の店舗</th><th class="num">件数</th><th>目的・会員番号</th>${admin?'<th>接続元</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr><td>${date(r.at,true)}</td><td><strong>${esc(r.actorName)}</strong><small>${esc(r.role)}・${esc(r.channel)}</small></td><td>${esc(r.action)}</td><td>${esc(r.target)}</td><td>${esc(salonName(r.salonId))}</td><td class="num">${r.count}</td><td>${esc(r.purpose||'—')}${r.refs?`<small>${esc(r.refs)}</small>`:''}</td>${admin?`<td>${esc(r.ip||'—')}</td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('記録はまだありません',admin?'美容室・ディーラーがお客様の情報を含む画面を開くと記録されます。':'')}</section>`;}
function viewContent(){return view==='overview'?overview():view==='access'?accessPage():view==='sales'?salesPage():view==='supply'?supplyPage():view==='invoices'?invoicesPage():view==='margins'?marginsPage():view==='orders'?`<section class="panel"><div class="panel-head"><h2>受注一覧 <span class="pill">${filterRows(data.orders).length} 件</span></h2></div>${filters(statuses)}${orderTable(filterRows(data.orders))}</section>`:view==='purchase'?`<section class="panel"><div class="panel-head"><h2>発注一覧 <span class="pill">${filterRows(data.purchaseOrders).length} 件</span></h2></div>${filters(poStatuses)}${purchaseTable(filterRows(data.purchaseOrders))}</section>`:view==='products'?productsPage():view==='salons'?salonsPage():view==='members'?membersPage():view==='settlements'?settlementsPage():`<section class="panel"><div class="panel-head"><h2>操作記録 <span class="pill">最新 ${data.events.length} 件</span></h2></div>${activityList(data.events)}</section>`;}
// 売上集計の結果は担当者ごとに異なるため、担当者が替わったら捨てる。
function resetSales(){sales=null;salesUnit='month';salesFrom='';salesTo='';}
async function reload(force=false){if(loading)return;loading=true;try{const auth=await platform('/operator/me');if(!auth.operator){resetSales();login();return;}if(auth.operator.id!==operator?.id){resetSales();data=null;}operator=auth.operator;const next=await platform('/admin/snapshot');if(force||!data||next.revision!==data.revision){data=next;if(view==='sales')await fetchSales();shell();}}catch(error){toast(error.message);}finally{loading=false;}}
function go(next,filter=''){view=next;query='';statusFilter=filter;salonFilter='';location.hash=next;document.body.classList.remove('menu-open');shell();scrollTo({top:0});if(view==='sales'&&!sales)loadSales().catch(formError);}
function orderDetail(id){const o=data.orders.find(o=>o.id===id);if(!o)return;modal('受注詳細',`<div class="between"><strong>${o.id}</strong>${badge(o.status,statuses[o.status])}</div><dl class="detail-list"><dt>販売店</dt><dd>${esc(o.salonName)} / ${esc(o.seller)}</dd>${o.customer.ref?`<dt>お客様</dt><dd>会員番号 ${esc(o.customer.ref)}<br><small>お客様の個人情報は担当サロンだけが閲覧できます</small></dd>`:`<dt>お客様</dt><dd>${esc(o.customer.name)} 様<br>${esc(o.customer.email)}<br><small>会員番号 ${esc(o.customerRef||'')}</small></dd><dt>お届け先</dt><dd>${esc(o.customer.address)}</dd>`}<dt>担当スタッフ</dt><dd>${esc(o.staffName)}</dd><dt>決済</dt><dd>${esc(o.payment)}</dd></dl>${o.items.map(p=>`<div class="order-line"><img src="./assets/${p.image}" alt=""><div class="line-copy"><strong>${esc(p.name)} × ${p.quantity}</strong><br><small>売価 ${money(p.price)} / 仕入 ${money(p.cost)}</small></div><b>${money(p.price*p.quantity)}</b></div>`).join('')}<div class="total-list"><div><span>商品小計</span><span>${money(o.subtotal)}</span></div><div><span>送料</span><span>${money(o.shipping)}</span></div><div class="grand"><span>注文合計</span><span>${money(o.total)}</span></div></div><h3>連動するディーラー発注</h3>${o.shipments.map(s=>`<div class="shipment"><div class="between"><b>${esc(s.dealerName)}</b>${badge(s.status,poStatuses[s.status])}</div><p>${s.id} ${s.tracking?' / '+esc(s.tracking):''}</p><button class="text-link" data-po="${s.id}">発注詳細へ ${icon('arrow')}</button></div>`).join('')}${o.returnReason?`<p class="return-reason">返品理由：${esc(o.returnReason)}</p>`:''}<ul class="timeline">${o.timeline.map(t=>`<li>${esc(t.label)}<time>${date(t.at,true)}</time></li>`).join('')}</ul><div class="form-actions">${['ordered','processing'].includes(o.status)?`<button class="btn danger" data-confirm-cancel="${o.id}">注文をキャンセル</button>`:''}${o.status==='return_requested'&&operator.role==='admin'?`<button class="btn primary" data-confirm-refund="${o.id}">返品検品・返金処理へ</button>`:''}<button class="btn outline" data-close>閉じる</button></div>`,true);}
function poDetail(id){const p=data.purchaseOrders.find(p=>p.id===id);if(!p)return;const order=data.orders.find(o=>o.id===p.orderId),locked=order&&['return_requested','returned','cancelled'].includes(order.status),editable=operator.role!=='salon'&&!locked;modal('ディーラー発注の詳細',`<div class="between"><strong>${p.id}</strong>${badge(p.status,poStatuses[p.status])}</div><dl class="detail-list"><dt>仕入先</dt><dd>${esc(data.dealers.find(d=>d.id===p.dealerId)?.name)}</dd><dt>販売サロン</dt><dd>${esc(p.salonName)}</dd><dt>出荷先</dt><dd>${p.customer.ref?`会員番号 ${esc(p.customer.ref)}<br><small>出荷先はディーラーと担当サロンだけが閲覧できます</small>`:`${esc(p.customer.name)} 様<br>${esc(p.customer.address)}`}</dd><dt>元の注文</dt><dd>${p.orderId}</dd></dl>${p.items.map(i=>`<div class="order-line"><div class="line-copy"><strong>${esc(i.name)}</strong><br><small>仕入 ${money(i.cost)} × ${i.quantity}</small></div><b>${money(i.cost*i.quantity)}</b></div>`).join('')}<div class="total-list"><div><span>配送費</span><span>${money(p.shipping)}</span></div><div class="grand"><span>発注合計</span><span>${money(p.total)}</span></div></div>${p.tracking?`<p class="notice">配送会社：${esc(p.carrier)}<br>追跡番号：${esc(p.tracking)}</p>`:''}${editable&&p.status==='accepted'?`<form id="ship-form" data-po-id="${p.id}" class="stack"><div class="form-grid"><label>配送会社<select name="carrier"><option>デモ配送</option><option>佐川急便（デモ）</option><option>ヤマト運輸（デモ）</option></select></label><label>追跡番号<input name="tracking" value="DEMO-${String(Date.now()).slice(-9)}" maxlength="60" pattern="[A-Za-z0-9\\-]+" required></label></div><div id="form-error" class="error" role="alert"></div><button class="btn primary" type="submit">出荷を確定して利用者へ反映</button></form>`:`<div class="form-actions">${editable&&p.status==='pending'?`<button class="btn primary" data-po-transition="${p.id}" data-status="accepted">発注を受け付ける</button>`:''}${editable&&p.status==='shipped'?`<button class="btn primary" data-po-transition="${p.id}" data-status="delivered">配達完了を記録</button>`:''}<button class="btn outline" data-close>閉じる</button></div>`}<p class="subtle-note">外部配送サービスへの送信や実際の配送は行われません。</p>`,true);}
function productEdit(id){const p=data.products.find(p=>p.id===id);modal('商品・在庫の編集',`<p>${esc(p.name)}</p><p class="subtle-note">${p.sku} / ${esc(data.dealers.find(d=>d.id===p.dealerId)?.name)}</p><form id="product-form" data-product-id="${id}" class="stack"><div class="form-grid">${operator.role==='admin'?`<label>税込売価（円）<input name="price" type="number" min="1" max="1000000" value="${p.price}" required></label><label>税込仕入単価（円）<input name="cost" type="number" min="0" max="1000000" value="${p.cost}" required></label><label>加盟店への卸価格（税込・円）<input name="wholesalePrice" type="number" min="0" max="1000000" value="${p.wholesalePrice}" required></label>`:''}<label>販売可能在庫（点）<input name="stock" type="number" min="0" max="99999" value="${p.stock}" required></label>${operator.role==='admin'?`<label class="check-label"><input name="enabled" type="checkbox" ${p.enabled?'checked':''}>利用者サイトで公開する</label>`:''}</div><p class="subtle-note">価格・仕入単価の変更は新しい注文に適用されます。過去の注文金額は変わりません。</p><div id="form-error" class="error" role="alert"></div><button class="btn primary" type="submit">保存してストアへ反映</button></form>`);}
