  // 店舗専用QR（仕様書 2.2.2）：URLは entry?shop_id=… 形式、PNG 600×600px、誤り訂正レベルM。
  if(b.dataset.salonLink){const s=data.salons.find(s=>s.id===b.dataset.salonLink),url=new URL('./',location.href);url.searchParams.set('shop_id',s.id);const qr=qrcode(0,'M');qr.addData(url.href);qr.make();modal('サロン紹介QR・リンク',`<h3>${esc(s.name)}<small class="subtle-note">　店舗ID ${esc(s.id)}</small></h3><p class="description">このQRからストアを開くと、サロンが選択されます。初めての会員登録時にサロンへ紐づきます。保存するQRは印刷用のPNG（600×600px・誤り訂正レベルM）です。</p><div class="qr-preview"><img src="${qr.createDataURL(5,20)}" alt="${esc(s.name)}の会員登録用QRコード" width="185" height="185"></div><div class="copy-row"><input id="salon-url" value="${esc(url.href)}" data-salon="${esc(s.id)}" readonly aria-label="サロン紹介URL"><button class="btn primary" data-copy-url>リンクをコピー</button></div><div class="form-actions"><button class="btn outline" data-download-qr>QRを保存（PNG） ${icon('download')}</button><a class="btn primary" href="${esc(url.href)}" target="_blank" rel="noopener">ストアを開く ${icon('external')}</a></div>${!isPages?'<p class="subtle-note">ローカル用URLです。別の端末で読み取る場合は公開版のQRをご利用ください。</p>':''}`);}
  if(b.hasAttribute('data-download-qr')){const input=$('#salon-url'),qr=qrcode(0,'M');qr.addData(input.value);qr.make();const size=600,count=qr.getModuleCount(),cell=Math.floor(size/(count+8)),offset=Math.floor((size-cell*count)/2),canvas=document.createElement('canvas');canvas.width=canvas.height=size;const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,size,size);ctx.fillStyle='#000000';for(let r=0;r<count;r++)for(let c=0;c<count;c++)if(qr.isDark(r,c))ctx.fillRect(offset+c*cell,offset+r*cell,cell,cell);await new Promise(resolve=>canvas.toBlob(blob=>{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`salon-${input.dataset.salon||'qr'}-qr-600.png`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);resolve();},'image/png'));toast('QRコード（PNG 600×600px）のダウンロードを開始しました。');}
