  if(b.hasAttribute('data-export'))await exportData();
  if(b.dataset.supply)supplyDetail(b.dataset.supply);
  if(b.dataset.supplyTransition){b.disabled=true;await platform('/admin/supply-orders/'+b.dataset.supplyTransition,'PATCH',{status:b.dataset.status});await reload(true);supplyDetail(b.dataset.supplyTransition);toast('加盟店発注を更新しました。');}
  if(b.dataset.supplyCancel){await platform('/supply/orders/'+b.dataset.supplyCancel+'/cancel','POST',{});await reload(true);supplyDetail(b.dataset.supplyCancel);toast('加盟店発注をキャンセルしました。');}
  if(b.hasAttribute('data-run-subs')){b.disabled=true;const r=await platform('/admin/supply/run','POST',{});await reload(true);toast(`定期発注：作成 ${r.created.length}件・作成できなかったもの ${r.failed.length}件`);}
