  if(b.dataset.invoice){currentInvoice=await platform('/supply/invoices/'+b.dataset.invoice);modal('請求書',`${invoiceHtml(currentInvoice)}<div class="form-actions no-print"><button class="btn outline" data-invoice-csv>CSVで保存</button><button class="btn primary" data-print>印刷・PDFで保存</button></div>`,true);}
  if(b.hasAttribute('data-invoice-csv')&&currentInvoice)downloadInvoiceCsv(currentInvoice);
