addEventListener('focus',()=>{if(operator&&!$('#modal').open)reload();});addEventListener('storage',()=>{if(operator&&!$('#modal').open)reload();});setInterval(()=>{if(operator&&!document.hidden&&!$('#modal').open)reload();},15000);
